<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password — c0m.me</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="auth-wrap"><a class="brand" href="/">c0m.me</a><section class="auth-card"><span class="eyebrow">ACCOUNT RECOVERY</span><h1><?= $valid ? 'Choose a new password' : 'Reset link unavailable' ?></h1><?php if ($valid): ?><form method="post" action="/reset-password"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><label>New password</label><input type="password" name="password" minlength="12" autocomplete="new-password" required><small>At least 12 characters, including uppercase, lowercase and a number.</small><button class="button full" type="submit">Update password</button></form><?php else: ?><p>This reset link is invalid, expired or already used. Request another link.</p><a class="button full" href="/forgot-password">Request reset link</a><?php endif; ?></section></main></body></html>
